constraints:
1 ≤ n ≤ 10^{4}
1 ≤ a[i] ≤ 10^{4}

expected time complexity: O(N).
expected auxiliary space: O(N).

standard_solution_code:
class Solution:

	def FindMaxSum(self, a, n):
		incl = 0
		excl = 0
		for i in a:
			new_excl = max(incl, excl)
			incl = excl + i
			excl = new_excl
		return max(incl, excl)
